cd ~/AppData/Local/Temp/tdeval-2-easy-slugify-RyuTYW && cat >> test/strings.test.js <<'EOF'

test('slugify lowercases and hyphenates', () => assert.strictEqual(slugify('Hello World'), 'hello-world'));
test('slugify strips Vietnamese diacritics', () =>
  assert.strictEqual(slugify('Đường Nguyễn Huệ, Quận 1'), 'duong-nguyen-hue-quan-1'));
test('slugify handles other Latin diacritics', () => assert.strictEqual(slugify('Crème Brûlée'), 'creme-brulee'));
test('slugify collapses runs of symbols', () => assert.strictEqual(slugify('a  --  b!!!c'), 'a-b-c'));
test('slugify trims leading and trailing hyphens', () => assert.strictEqual(slugify('  ?Hello!  '), 'hello'));
test('slugify empty or symbol-only input', () => {
  assert.strictEqual(slugify(''), '');
  assert.strictEqual(slugify('!!!'), '');
});
test('slugify limits to 50 characters', () => assert.strictEqual(slugify('a'.repeat(80)), 'a'.repeat(50)));
test('slugify cut at 50 does not end with hyphen', () => {
  const s = slugify('a'.repeat(49) + ' bcd');
  assert.strictEqual(s, 'a'.repeat(49));
});
EOF
